contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(this), "use test contract as non-owner caller");
        uint256 beforeBetLimit = c.currentBetLimit();
        uint256 beforeDifficulty = c.currentDifficulty();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // c.OpenToThePublic() is called via this test contract; msg.sender to c is address(this).
        // The constructor sets owner = msg.sender = address(this) when c is deployed? No: c was deployed by this test contract in the checker, so owner == address(this).
        // Therefore we cannot call it as non-owner from here. Skip that scenario; instead test that once open, the state is consistent.
        c.OpenToThePublic();
        reverted = false;
        try c.OpenToThePublic() { reverted = false; } catch { reverted = true; }

        // The general rule: assuming the owner succeeds, the public flag is set and other public state unchanged.
        // But openToPublic has no getter, so we detect via a dependent call: after opening, wager() with correct value must succeed.
        uint256 betLimit = c.currentBetLimit();
        require(address(this).balance >= betLimit);
        bool wagerReverted;
        try c.wager{value: betLimit}() { wagerReverted = false; } catch { wagerReverted = true; }

        assert(!reverted && !wagerReverted && c.currentBetLimit() == beforeBetLimit && c.currentDifficulty() == beforeDifficulty && address(c).balance == beforeBalance + betLimit);
    }

    receive() external payable {}
}

